use fastcdc::{v2016, v2020};

const EXPECTED: &[(usize, usize)] = &[
    (0, 100081),
    (100081, 33106),
    (133187, 69903),
    (203090, 49442),
    (252532, 103705),
    (356237, 144977),
    (501214, 214287),
    (715501, 145480),
    (860981, 50981),
    (911962, 37677),
    (949639, 79457),
    (1029096, 19480),
];

const PRESETS: &[(usize, usize, usize)] = &[
    (16 * 1024, 64 * 1024, 256 * 1024),
    (32 * 1024, 128 * 1024, 512 * 1024),
    (64 * 1024, 256 * 1024, 1024 * 1024),
];

// FNV-1a 64 digests of the ChunkShift scalar cut lists, generated by the
// independent Python reference (tools/reference/fastcdc_reference.py
// --print-fixture-digests) for (fixture, target). #99 L1.
